// popcount: Population count of a 256-bit word. Naive: count all 256 bits in one cycle.
// Latency contract: an input applied before clock edge n shows on the outputs after edge n+LATENCY-1.
module popcount (
    input  wire         clk,
    input  wire         rst,
    input  wire [255:0] din,
    output wire [8:0]   count
);
    localparam LATENCY = 2;
    reg [255:0] din_r;
    reg [8:0]   count_r;
    integer k;
    reg [8:0] acc;
    always @(*) begin
        acc = 0;
        for (k = 0; k < 256; k = k + 1) acc = acc + din_r[k];
    end
    always @(posedge clk) begin
        if (rst) begin
            din_r <= 0; count_r <= 0;
        end else begin
            din_r <= din;
            count_r <= acc;
        end
    end
    assign count = count_r;
endmodule

// popcount, 2-level: sixteen 16-bit group counts, then one 16-way sum.
// stages: din_r(1) -> g_r: 16 x 5-bit group counts(2) -> count_r(3)
module popcount (
    input  wire         clk,
    input  wire         rst,
    input  wire [255:0] din,
    output wire [8:0]   count
);
    localparam LATENCY = 3;
    reg [255:0] din_r;
    reg [79:0]  g_r;     // 16 x 5-bit counts of 16 bits each (0..16)
    reg [8:0]   count_r;
    reg [4:0]   g;
    reg [8:0]   acc;
    integer i, k;
    always @(posedge clk) begin
        if (rst) begin
            din_r <= 0; g_r <= 0; count_r <= 0;
        end else begin
            din_r <= din;
            for (i = 0; i < 16; i = i + 1) begin
                g = 0;
                for (k = 0; k < 16; k = k + 1) g = g + din_r[i*16 + k];
                g_r[i*5 +: 5] <= g;
            end
            acc = 0;
            for (i = 0; i < 16; i = i + 1) acc = acc + g_r[i*5 +: 5];
            count_r <= acc;
        end
    end
    assign count = count_r;
endmodule

// popcount, pipelined: the design a fresh agent reached through ManuDesk's check() loop.
// stages: din_r(1) -> nib_r: 64 x 4-bit counts(2) -> s1_r: 16 sums(3) -> s2_r: 4 sums(4) -> count_r(5)
module popcount (
    input  wire         clk,
    input  wire         rst,
    input  wire [255:0] din,
    output wire [8:0]   count
);
    localparam LATENCY = 5;
    reg [255:0] din_r;
    reg [191:0] nib_r;   // 64 x 3-bit counts of 4 bits each (0..4)
    reg [79:0]  s1_r;    // 16 x 5-bit sums of 4 nibble counts (0..16)
    reg [27:0]  s2_r;    // 4 x 7-bit sums (0..64)
    reg [8:0]   count_r;
    integer i;
    always @(posedge clk) begin
        if (rst) begin
            din_r <= 0; nib_r <= 0; s1_r <= 0; s2_r <= 0; count_r <= 0;
        end else begin
            din_r <= din;
            for (i = 0; i < 64; i = i + 1)
                nib_r[i*3 +: 3] <= din_r[i*4] + din_r[i*4+1] + din_r[i*4+2] + din_r[i*4+3];
            for (i = 0; i < 16; i = i + 1)
                s1_r[i*5 +: 5] <= nib_r[(i*4)*3 +: 3] + nib_r[(i*4+1)*3 +: 3]
                                + nib_r[(i*4+2)*3 +: 3] + nib_r[(i*4+3)*3 +: 3];
            for (i = 0; i < 4; i = i + 1)
                s2_r[i*7 +: 7] <= s1_r[(i*4)*5 +: 5] + s1_r[(i*4+1)*5 +: 5]
                                + s1_r[(i*4+2)*5 +: 5] + s1_r[(i*4+3)*5 +: 5];
            count_r <= s2_r[6:0] + s2_r[13:7] + s2_r[20:14] + s2_r[27:21];
        end
    end
    assign count = count_r;
endmodule

// popcount, 6-stage adder tree: 4-bit counts, then 4-way sums, final add split in two.
// stages: din_r(1) -> nib_r(2) -> s1_r: 16 sums(3) -> s2_r: 4 sums(4) -> s3_r: 2 sums(5) -> count_r(6)
module popcount (
    input  wire         clk,
    input  wire         rst,
    input  wire [255:0] din,
    output wire [8:0]   count
);
    localparam LATENCY = 6;
    reg [255:0] din_r;
    reg [191:0] nib_r;   // 64 x 3-bit counts of 4 bits each (0..4)
    reg [79:0]  s1_r;    // 16 x 5-bit sums of 4 nibble counts (0..16)
    reg [27:0]  s2_r;    // 4 x 7-bit sums (0..64)
    reg [15:0]  s3_r;    // 2 x 8-bit sums (0..128)
    reg [8:0]   count_r;
    integer i;
    always @(posedge clk) begin
        if (rst) begin
            din_r <= 0; nib_r <= 0; s1_r <= 0; s2_r <= 0; s3_r <= 0; count_r <= 0;
        end else begin
            din_r <= din;
            for (i = 0; i < 64; i = i + 1)
                nib_r[i*3 +: 3] <= din_r[i*4] + din_r[i*4+1] + din_r[i*4+2] + din_r[i*4+3];
            for (i = 0; i < 16; i = i + 1)
                s1_r[i*5 +: 5] <= nib_r[(i*4)*3 +: 3] + nib_r[(i*4+1)*3 +: 3]
                                + nib_r[(i*4+2)*3 +: 3] + nib_r[(i*4+3)*3 +: 3];
            for (i = 0; i < 4; i = i + 1)
                s2_r[i*7 +: 7] <= s1_r[(i*4)*5 +: 5] + s1_r[(i*4+1)*5 +: 5]
                                + s1_r[(i*4+2)*5 +: 5] + s1_r[(i*4+3)*5 +: 5];
            s3_r[7:0]  <= s2_r[6:0]   + s2_r[13:7];
            s3_r[15:8] <= s2_r[20:14] + s2_r[27:21];
            count_r <= s3_r[7:0] + s3_r[15:8];
        end
    end
    assign count = count_r;
endmodule
